solution.code:
def jadwalkan_semua(pods, nodes):
    pakai = {n["nama"]: [0, 0] for n in nodes}
    hasil = {}
    for pod in pods:
        layak = []
        for n in nodes:
            if any(n["labels"].get(k) != v for k, v in pod["selector"].items()):
                continue
            sisa_cpu = n["cpu_m"] - pakai[n["nama"]][0]
            sisa_mem = n["mem_mi"] - pakai[n["nama"]][1]
            if sisa_cpu >= pod["cpu_m"] and sisa_mem >= pod["mem_mi"]:
                layak.append((-sisa_cpu, n["nama"]))
        if layak:
            nama = min(layak)[1]
            pakai[nama][0] += pod["cpu_m"]
            pakai[nama][1] += pod["mem_mi"]
            hasil[pod["nama"]] = nama
        else:
            hasil[pod["nama"]] = None
    return hasil


def ringkasan(hasil):
    pending = sorted(nama for nama, node in hasil.items() if node is None)
    return (len(hasil) - len(pending), pending)


def sisa_node(node, pods, hasil):
    cpu, mem = node["cpu_m"], node["mem_mi"]
    for pod in pods:
        if hasil.get(pod["nama"]) == node["nama"]:
            cpu -= pod["cpu_m"]
            mem -= pod["mem_mi"]
    return (cpu, mem)

