solution.code:
def _angka(nilai, replicas, ke_atas):
    if isinstance(nilai, str) and nilai.endswith("%"):
        persen = int(nilai[:-1])
        total = replicas * persen
        if ke_atas:
            return -(-total // 100)
        return total // 100
    return int(nilai)


def batas_rolling(replicas, max_surge, max_unavailable):
    surge = _angka(max_surge, replicas, True)
    tidak_siap = _angka(max_unavailable, replicas, False)
    return (replicas + surge, replicas - tidak_siap)

