def revisi_rollback(riwayat, ke=None):
    if ke is None:
        if len(riwayat) < 2:
            raise ValueError("tidak ada revisi sebelumnya")
        return riwayat[-2]["image"]
    for r in riwayat:
        if r["revisi"] == ke:
            return r["image"]
    raise ValueError("revisi tidak ditemukan")

