def _di_bawah(path, awalan):
    if awalan == "/":
        return True
    return path == awalan or path.startswith(awalan + "/")


def rute_ingress(aturan, host, path):
    terbaik = None
    for a in aturan:
        if a["host"] != host or not _di_bawah(path, a["path"]):
            continue
        if terbaik is None or len(a["path"]) > len(terbaik["path"]):
            terbaik = a
    return terbaik["service"] if terbaik else None

