solution.code:
def _guaranteed(c):
    for sumber in ("cpu", "memory"):
        req = c["requests"].get(sumber)
        lim = c["limits"].get(sumber)
        if req is None or lim is None or req != lim:
            return False
    return True


def kelas_qos(containers):
    kosong = all(not c["requests"] and not c["limits"] for c in containers)
    if kosong:
        return "BestEffort"
    if all(_guaranteed(c) for c in containers):
        return "Guaranteed"
    return "Burstable"

