solution.code:
def boleh(bindings, user, verb, resource, ns):
    for b in bindings:
        if b["user"] != user or b["ns"] not in (ns, "*"):
            continue
        for aturan in b["rules"]:
            if verb in aturan["verbs"] or "*" in aturan["verbs"]:
                if resource in aturan["resources"] or "*" in aturan["resources"]:
                    return True
    return False

