solution.code:
def diagnosa(pod):
    status = pod["status"]
    if status == "Pending" and any("Insufficient" in e for e in pod["events"]):
        return "kapasitas"
    if status in ("ImagePullBackOff", "ErrImagePull"):
        return "image"
    if status == "CrashLoopBackOff":
        return "memori" if pod["last_reason"] == "OOMKilled" else "aplikasi"
    if status == "Running" and not pod["ready"]:
        return "readiness"
    return "sehat"
